#include <cmath>
#include <cstdlib>
#include <complex>
#include <constants_mod.hpp>
#include <nf_mod.hpp>
#include <mxpart_mod.hpp>
#include <ckm_mod.hpp>
#include <ckm1_mod.hpp>
#include <ewcouple_mod.hpp>
#include <zcouple_mod.hpp>
#include <Cabibbo_mod.hpp>
#include <first_mod.hpp>
#include <blha_mod.hpp>
#include <FArray.hpp>
#include <Need.hpp>

void ckmfill(int nwz) {
    using namespace constants_mod;
    using namespace nf_mod;
    using namespace mxpart_mod;
    using namespace ckm_mod;
    using namespace ckm1_mod;
    using namespace ewcouple_mod;
    using namespace zcouple_mod;
    using namespace Cabibbo_mod;
    using namespace first_mod;
    using namespace blha_mod;

    // Initialize if using 'CKMrotate'
    if (first) {
        if (CKMdiag) {
            Vud = 1.0;
            Vus = 0.0;
            Vub = 0.0;
            Vcd = 0.0;
            Vcs = 1.0;
            Vcb = 0.0;
        }

        if (CKMrotate) {
            Vud_rotate = Vud;
            Vus_rotate = Vus;
            Vub_rotate = Vub;
            Vcd_rotate = Vcd;
            Vcs_rotate = Vcs;
            Vcb_rotate = Vcb;
            Vud = 1.0;
            Vus = 0.0;
            Vub = 0.0;
            Vcd = 0.0;
            Vcs = 1.0;
            Vcb = 0.0;
        }

        first = false;
    }

    // Initialize Vsq
    Vsq.fill(0.0);

    // Set other couplings to zero
    flsq = 0.0;
    frsq = 0.0;
    fl = 0.0;
    fr = 0.0;

    for (int j = -nf; j <= nf; j++) {
        for (int k = -nf; k <= nf; k++) {
            gl(j, k) = 0.0;
            gr(j, k) = 0.0;
            glsq(j, k) = 0.0;
            grsq(j, k) = 0.0;
        }
    }

    // Case BLHA
    if (useblha == 1) {
        Vsq(2, -1) = Vud * Vud;
        Vsq(2, -3) = Vus * Vus;
        Vsq(2, -5) = Vub * Vub;
        Vsq(4, -1) = Vcd * Vcd;
        Vsq(4, -3) = Vcs * Vcs;
        Vsq(4, -5) = Vcb * Vcb;
        Vsq(1, -2) = Vud * Vud;
        Vsq(3, -2) = Vus * Vus;
        Vsq(5, -2) = Vub * Vub;
        Vsq(1, -4) = Vcd * Vcd;
        Vsq(3, -4) = Vcs * Vcs;
        Vsq(5, -4) = Vcb * Vcb;
    }

    // Case Z0
    if (nwz == 0) {
        Vsq(1, -1) = 1.0;
        Vsq(2, -2) = 1.0;
        Vsq(3, -3) = 1.0;
        Vsq(4, -4) = 1.0;
        Vsq(5, -5) = 1.0;
        double rtxw = std::sqrt(xw);
        for (int j = 1; j <= 5; j++) {
            gl(+j, -j) = l(j) * gw * rtxw;
            gr(+j, -j) = r(j) * gw * rtxw;
        }
        fl = le * gw * rtxw;
        fr = re * gw * rtxw;
        for (int j = 1; j <= nf; j++) {
            glsq(j, -j) = std::pow(gl(j, -j), 2);
            grsq(j, -j) = std::pow(gr(j, -j), 2);
        }
        flsq = std::pow(fl, 2);
        frsq = std::pow(fr, 2);
        return;
    }

    // Case W+
    else if (nwz == 1) {
        Vsq(2, -1) = Vud * Vud;
        Vsq(2, -3) = Vus * Vus;
        Vsq(2, -5) = Vub * Vub;
        Vsq(4, -1) = Vcd * Vcd;
        Vsq(4, -3) = Vcs * Vcs;
        Vsq(4, -5) = Vcb * Vcb;

        glsq(2, -1) = gwsq / 2.0;
        glsq(2, -3) = gwsq / 2.0;
        glsq(2, -5) = gwsq / 2.0;
        glsq(4, -1) = gwsq / 2.0;
        glsq(4, -3) = gwsq / 2.0;
        glsq(4, -5) = gwsq / 2.0;
        flsq = gwsq / 2.0;
        fl = std::sqrt(flsq);
    }

    // Case W-
    else if (nwz == -1) {
        Vsq(1, -2) = Vud * Vud;
        Vsq(3, -2) = Vus * Vus;
        Vsq(5, -2) = Vub * Vub;
        Vsq(1, -4) = Vcd * Vcd;
        Vsq(3, -4) = Vcs * Vcs;
        Vsq(5, -4) = Vcb * Vcb;

        glsq(1, -2) = gwsq / 2.0;
        glsq(3, -2) = gwsq / 2.0;
        glsq(5, -2) = gwsq / 2.0;
        glsq(1, -4) = gwsq / 2.0;
        glsq(3, -4) = gwsq / 2.0;
        glsq(5, -4) = gwsq / 2.0;
        flsq = gwsq / 2.0;
        fl = std::sqrt(flsq);
    }

    // Case (W+ + W-)
    else if (nwz == 2) {
        // Case W+
        Vsq(2, -1) = Vud * Vud;
        Vsq(2, -3) = Vus * Vus;
        Vsq(2, -5) = Vub * Vub;
        Vsq(4, -1) = Vcd * Vcd;
        Vsq(4, -3) = Vcs * Vcs;
        Vsq(4, -5) = Vcb * Vcb;
        glsq(2, -1) = gwsq / 2.0;
        glsq(2, -3) = gwsq / 2.0;
        glsq(2, -5) = gwsq / 2.0;
        glsq(4, -1) = gwsq / 2.0;
        glsq(4, -3) = gwsq / 2.0;
        glsq(4, -5) = gwsq / 2.0;
        // Case W-
        Vsq(1, -2) = Vud * Vud;
        Vsq(3, -2) = Vus * Vus;
        Vsq(5, -2) = Vub * Vub;
        Vsq(1, -4) = Vcd * Vcd;
        Vsq(3, -4) = Vcs * Vcs;
        Vsq(5, -4) = Vcb * Vcb;
        glsq(1, -2) = gwsq / 2.0;
        glsq(3, -2) = gwsq / 2.0;
        glsq(5, -2) = gwsq / 2.0;
        glsq(1, -4) = gwsq / 2.0;
        glsq(3, -4) = gwsq / 2.0;
        glsq(5, -4) = gwsq / 2.0;

        flsq = gwsq / 2.0;
        fl = std::sqrt(flsq);
    }

    for (int j = -nf; j <= nf; j++) {
        for (int k = -nf; k <= nf; k++) {
            Vsq(j, k) = Vsq(k, j);
            glsq(j, k) = glsq(k, j);
            grsq(j, k) = grsq(k, j);
            VV(j, k) = std::sqrt(Vsq(j, k));
            gl(j, k) = std::sqrt(glsq(j, k));
            gr(j, k) = std::sqrt(grsq(j, k));
        }
    }
    for (int j = 1; j <= 5; j++) {
        Vsum(+j) = Vsq(+j, -1) + Vsq(+j, -2) + Vsq(+j, -3) + Vsq(+j, -4) + Vsq(+j, -5);
        Vsum(-j) = Vsq(-j, +1) + Vsq(-j, +2) + Vsq(-j, +3) + Vsq(-j, +4) + Vsq(-j, +5);
    }
    Vsum(0) = 0.0;
    return;
}

extern "C" {
  void ckmfill_wrapper(int nwz) {
    ckmfill(nwz);
  }
}
