   interface
      subroutine ckmfill_wrapper(nwz) bind(C, name="ckmfill_wrapper")
         import :: c_int
         integer(c_int), value :: nwz
      end subroutine ckmfill_wrapper
   end interface

   call ckmfill_wrapper(nwz)

end subroutine
