//  Copyright (C) 2019-2022, respective authors of MCFM.
//

#include <storecsz.hpp>
#include <FArray.hpp>
#include <mmsq_cs_mod.hpp>

using namespace mmsq_cs_mod;

// this routine transfers the information on the colour structure
// for the Z2jet matrix elements into separate arrays for each
// incoming parton case
void storecsz(FArray3D<double>& mcs) {
  for (int i = 0; i <= 2; i++) {
    for (int j = 1; j <= 2; j++) {
      for (int k = 1; k <= 2; k++) {
        mcs(i,j,k) = mmsq_cs(i,j,k); // @coverage-probe
      }
    }
  }
  return;
}

extern "C" {
  void storecsz_wrapper(double* fmcs) {
    FArray3D<double> mcs(fmcs, 3, 2, 2, 0, 1, 1);
    storecsz(mcs);
  }
}

