namespace {

// Small helpers reproducing the Fortran fixed-width character semantics
// used by the diagnostic banner below (pname is declared character(len=256),
// pwrite character(len=82)), so that the 1-based substring math matches the
// original line for line.

std::string ffit(const std::string& s, size_t width) {
  if (s.size() >= width) return s.substr(0, width);
  return s + std::string(width - s.size(), ' ');
}

std::string fadjustl(const std::string& s) {
  size_t i = 0;
  while (i < s.size() && s[i] == ' ') ++i;
  return s.substr(i) + std::string(i, ' ');
}

std::string fsubstr(const std::string& s, int lo, int hi) {
  if (hi < lo) return std::string();
  int n = static_cast<int>(s.size());
  if (lo < 1) lo = 1;
  if (hi > n) hi = n;
  if (hi < lo) return std::string();
  return s.substr(lo - 1, hi - lo + 1);
}

bool fstreq(const std::string& a, const std::string& b) {
  size_t n = std::max(a.size(), b.size());
  std::string pa(a), pb(b);
  pa.resize(n, ' ');
  pb.resize(n, ' ');
  return pa == pb;
}

int findex(const std::string& s, const std::string& sub) {
  size_t p = s.find(sub);
  return p == std::string::npos ? 0 : static_cast<int>(p) + 1;
}

// Mirrors the original list-directed `read(21,*,err=44) mproc,pname,order`
// against the quoted records in process.DAT, e.g.
//   1  '  f(p1)+f(p2) --> W^+(-->nu(p3)+e^+(p4))' 'N'
bool read_process_record(std::ifstream& in, int& mproc, std::string& pname, char& order) {
  std::string line;
  if (!std::getline(in, line)) return false;
  std::istringstream iss(line);
  if (!(iss >> mproc)) return false;
  size_t q1 = line.find('\'');
  if (q1 == std::string::npos) return false;
  size_t q2 = line.find('\'', q1 + 1);
  if (q2 == std::string::npos) return false;
  pname = ffit(line.substr(q1 + 1, q2 - q1 - 1), 256);
  size_t q3 = line.find('\'', q2 + 1);
  if (q3 == std::string::npos) return false;
  size_t q4 = line.find('\'', q3 + 1);
  if (q4 == std::string::npos) return false;
  std::string ord = line.substr(q3 + 1, q4 - q3 - 1);
  order = ord.empty() ? ' ' : ord[0];
  return true;
}

