  // C array (plabel_mod.hpp); this local helper keeps every plabel(N)=...
  // assignment below at the correct -1 offset.
  auto setplabel = [&](int idx, const char* val) { std::strcpy(plabel[idx - 1], val); };

  std::strcpy(hdecaymode, "xxxx");

  for (j = 1; j <= mxpart; j++) {
    setplabel(j, "  ");
  }

  std::ifstream fin21("process.DAT");
  if (!fin21.is_open()) goto L43;

  if (verbose) {
    std::printf("Chooser: process chosen by nproc = %3d\n", nproc);
  }

  for (j = 1; j <= 600; j++) {
    if (!read_process_record(fin21, mproc, pname, order)) goto L44;

    if (nproc < 0) {
      std::cout << mproc << " " << pname << std::endl;
    }
    if (mproc == nproc) goto L42;
    if (fstreq(pname, "EOF")) goto L44;
  }
  goto L44;

  L42:;
  if (verbose && first) {
    std::cout << std::endl;
    std::cout << "*************************** f(p1)+f(p2) --> *****"
                 "*************************************" << std::endl;
    j = findex(pname, "[");
    if (j > 101) j = 101;
    if (j > 0) {
      pwrite = ffit(fadjustl(fsubstr(pname, 19, j - 1)), 82);
      std::cout << " * " << pwrite << " *" << std::endl;
      pwrite = ffit(fadjustl(fsubstr(pname, j, static_cast<int>(pname.size()))), 82);
      std::cout << " * " << pwrite << " *" << std::endl;
    } else {
      pwrite = ffit(fadjustl(fsubstr(pname, 19, 100)), 82);
      std::cout << " * " << pwrite << " *" << std::endl;
    }
    std::cout << "*************************************************"
                 "*************************************" << std::endl;
    std::cout << std::endl;
  }
  fin21.close();

  // check no. of momenta appearing in LO process, fill ilomomenta common block
  if (first) {
    if (findex(pname, "p3") > 0)  ilomomenta = 3;
    if (findex(pname, "p4") > 0)  ilomomenta = 4;
    if (findex(pname, "p5") > 0)  ilomomenta = 5;
    if (findex(pname, "p6") > 0)  ilomomenta = 6;
    if (findex(pname, "p7") > 0)  ilomomenta = 7;
    if (findex(pname, "p8") > 0)  ilomomenta = 8;
    if (findex(pname, "p9") > 0)  ilomomenta = 9;
    if (findex(pname, "p10") > 0) ilomomenta = 10;
    if (findex(pname, "p11") > 0) ilomomenta = 11;
    if (findex(pname, "p12") > 0) ilomomenta = 12;
  }

  setplabel(1, "pp");
  setplabel(2, "pp");

  // the default behaviour is to remove no branching ratio
  BrnRat = 1.0;

  // catch processes for which complex mass scheme should be enforced
  if (kcase == kWln_ew) {
    ewscheme = 4;
  }
  // set up most parameters
  coupling();

  nqcdjets = 0;
  isub = 0;
  nodecay = false;
  reset_alphaEM = false;

  // Rbbmin is an additional variable, added so that the separation
  // between two b jets can be controlled separately from the Delta_R
  // cut between any other types of jet.
  // Default behaviour: the same value as for the other jets
  Rbbmin = Rcut;

  if ((nproc == 1) || (nproc == 6)) {
    kcase = kW_only;
    mass3 = wmass;
    width3 = wwidth;
    n3 = 1;
    nqcdjets = 0;

    // W^+
    if (nproc == 1) {
      // 1  '  f(p1)+f(p2) --> W^+(-->nu(p3)+e^+(p4))'
      //    '  f(p1)+f(p2) --> W^+ (for total Xsect)' (removebr=.true.)
      setplabel(3, "nl");
      setplabel(4, "ea");
      setplabel(5, "pp");
      nwz = 1;
      // W^-
    } else if (nproc == 6) {
      // 6  '  f(p1)+f(p2) --> W^-(-->e^-(p3)+nu~(p4))'
      //    '  f(p1)+f(p2) --> W^- (for total Xsect)' (removebr=.true.)
      setplabel(3, "el");
      setplabel(4, "na");
      setplabel(5, "pp");
      nwz = -1;
    } else {
      nprocinvalid();
    }

    // total cross-section
    if (removebr) {
      BrnRat = brwen;
