      setplabel(3, "qb");
      setplabel(4, "ab");
      q1 = Q(5) * std::sqrt(xn);
      l1 = l(5) * std::sqrt(xn);
      r1 = r(5) * std::sqrt(xn);
    }

  } else if (nproc == 44) {
    // 44 '  f(p1)+f(p2) --> Z^0(-->e^-(p3)+e^+(p4))+f(p5)+f(p6)'
    //    '  f(p1)+f(p2) --> Z^0 (no BR) +f(p5)+f(p6)' (removebr=.true.)
    kcase = kZ_2jet;
    checkminzmass(1);
    n2 = 0;
    n3 = 1;
    nqcdjets = 2;
    setplabel(3, "el");
    setplabel(4, "ea");
    setplabel(5, "pp");
    setplabel(6, "pp");
    setplabel(7, "pp");
    q1 = -1.0;
    l1 = le;
    r1 = re;
    zl1 = zle;
    zr1 = zre;
    nwz = 0;
    mass3 = zmass;
    width3 = zwidth;

    toploops = texact; // exact treatment of top-quark loops
    toplight = true;
    topaxial = true;
    topvector = true;

    // total cross-section
    if (removebr) {
      setplabel(3, "ig");
      setplabel(4, "ig");
      BrnRat = brzee;
    }

  } else if (nproc == 45) {
    // 45 '  f(p1)+f(p2) --> Z^0(-->e^-(p3)+e^+(p4))+f(p5)+f(p6)+f(p7)'
    //    '  f(p1)+f(p2) --> Z^0 (no BR) +f(p5)+f(p6)+f(p7)' (removebr=.true.)
    kcase = kZ_3jet;
    checkminzmass(1);
    n2 = 0;
    n3 = 1;
    nqcdjets = 3;
    setplabel(3, "el");
    setplabel(4, "ea");
    setplabel(5, "pp");
    setplabel(6, "pp");
    setplabel(7, "pp");
    q1 = -1.0;
    l1 = le;
    r1 = re;
    zl1 = zle;
    zr1 = zre;
    nwz = 0;
    mass3 = zmass;
    width3 = zwidth;

    // total cross-section
    if (removebr) {
      setplabel(3, "ig");
      setplabel(4, "ig");
      BrnRat = brzee;
    }

  } else if (nproc == 46) {
    // 46 '  f(p1)+f(p2) --> Z^0(-->3*(nu(p3)+nu~(p4))+f(p5)+f(p6)'
    kcase = kZ_2jet;
    n2 = 0;
    n3 = 1;
    nqcdjets = 2;
    setplabel(3, "nl");
    setplabel(4, "na");
    setplabel(5, "pp");
    setplabel(6, "pp");
    setplabel(7, "pp");
    q1 = zip;
    l1 = ln * std::sqrt(3.0);
    r1 = rn * std::sqrt(3.0);
    zl1 = zln * std::sqrt(3.0);
    zr1 = zrn * std::sqrt(3.0);
    nwz = 0;
    mass3 = zmass;
    width3 = zwidth;

    toploops = texact; // exact treatment of top-quark loops
    toplight = true;
    topaxial = true;
    topvector = true;

    // total cross-section
    if (removebr) {
      setplabel(3, "ig");
      setplabel(4, "ig");
      BrnRat = brznn;
    }

  } else if (nproc == 47) {
    // 47 '  f(p1)+f(p2) --> Z^0(-->3*(nu(p3)+nu~(p4))+f(p5)+f(p6)+f(p7)'
    kcase = kZ_3jet;
    n2 = 0;
    n3 = 1;
    nqcdjets = 3;
    setplabel(3, "nl");
    setplabel(4, "na");
    setplabel(5, "pp");
    setplabel(6, "pp");
    setplabel(7, "pp");
    q1 = zip;
    l1 = ln * std::sqrt(3.0);
    r1 = rn * std::sqrt(3.0);
    zl1 = zln * std::sqrt(3.0);
    zr1 = zrn * std::sqrt(3.0);
    nwz = 0;
    mass3 = zmass;
    width3 = zwidth;

    // total cross-section
    if (removebr) {
      setplabel(3, "ig");
      setplabel(4, "ig");
      BrnRat = brznn;
    }

  } else if ((nproc == 111) || (nproc == 112) || (nproc == 119)) {
    kcase = kggfus0;
    setplabel(5, "pp");

    n2 = 0;
    n3 = 1;
    mass3 = hmass;
    width3 = hwidth;

    if (nproc == 111) {
      // 111 '  f(p1)+f(p2) --> H(-->b(p3)+bbar(p4))'
      //     '  f(p1)+f(p2) --> H (for total Xsect)' (removebr=.true.)
      std::strcpy(hdecaymode, "bqba");
      setplabel(3, "bq");
      setplabel(4, "ba");
      nqcdjets = 2;
      if (removebr) {
        setplabel(3, "ig");
        setplabel(4, "ig");
        nqcdjets = 0;
        BrnRat = br;
      }

    } else if (nproc == 112) {
      // 112 '  f(p1)+f(p2) --> H(-->tau^-(p3)+tau^+(p4))'
      //     '  f(p1)+f(p2) --> H (for total Xsect)' (removebr=.true.)
      std::strcpy(hdecaymode, "tlta");
      setplabel(3, "tl");
      setplabel(4, "ta");
      nqcdjets = 0;
      if (removebr) {
        setplabel(3, "ig");
        setplabel(4, "ig");
        BrnRat = tautaubr;
      }

    } else if (nproc == 119) {
      // 119 '  f(p1)+f(p2) --> H(-->gamma^-(p3)+gamma^+(p4))'
      //     '  f(p1)+f(p2) --> H (for total Xsect)' (removebr=.true.)
      std::strcpy(hdecaymode, "gaga");
      setplabel(3, "ga");
      setplabel(4, "ga");
      std::strcpy(hdecaymode, "gaga");
      nqcdjets = 0;
      if (removebr) {
        setplabel(3, "ig");
        setplabel(4, "ig");
        BrnRat = gamgambr;
      }
    }

  } else if ((nproc == 269) || (nproc == 270) || (nproc == 2691)
             || (nproc == 271) || (nproc == 272)) {

    // turn off Higgs decay, for speed
    // parameters to turn off various pieces, for checking

    setplabel(5, "pp");
    setplabel(6, "pp");
    setplabel(7, "pp");

    n2 = 0;
    n3 = 1;

    mass3 = hmass;
    width3 = hwidth;

    if ((nproc == 269) || (nproc == 270)) {
      // 270 '  f(p1)+f(p2) --> H(gamma(p3)+gamma(p4))+f(p5)+f(p6)[in heavy top limit]'
      //     '  f(p1)+f(p2) --> H(no BR)+f(p5)+f(p6)[in heavy top limit]' (removebr=.true.)
      std::strcpy(hdecaymode, "gaga");
      setplabel(3, "ga");
      setplabel(4, "ga");
      kcase = kgagajj;
      if (nproc == 269) kcase = kh2jmas;
      nqcdjets = 2;
      if (removebr) {
        setplabel(3, "ig");
        setplabel(4, "ig");
        BrnRat = gamgambr;
      }
    }

  } else {
    nprocinvalid();
  }

  // report on the removed BR, if necessary
  if (removebr) {
    std::cout << "****************************************************" << std::endl;
    if (BrnRat != 1.0) {
      std::cout << "*             Setting zerowidth to .true.          *" << std::endl;
      zerowidth = true;
    }
    std::printf(" *             Brn.Rat. removed = %11.7f       *\n", BrnRat);
    std::cout << "****************************************************" << std::endl;
  }

  // if needed for photon processes reset to 1/137.0
  if (useblha == 0) {
    if (reset_alphaEM) {
      double reset_aem_arg = 1.0 / 137.0;
      reset_aem_(&reset_aem_arg);
    }
  }

  // fill up CKM matrix
  ckmfill(nwz);

  // set flags to true unless we're doing W+2 jet or Z+2 jet
  if (((kcase != kW_2jet) && (kcase != kZ_2jet)) || (kpart == klord)) {
    Qflag = true;
    Gflag = true;
  }

  // fix complex-mass scheme couplings in case not already set above!
  fixcms(l1, zl1);
  fixcms(r1, zr1);
  fixcms(l2, zl2);
  fixcms(r2, zr2);

  if (first) first = false;

  return;

  L43:
  std::cout << "problems opening process.DAT" << std::endl;
  std::exit(1);

  L44:
  std::cout << "Unimplemented process number, nproc = " << nproc
            << " mcfm halted" << std::endl;
  std::exit(1);
}

static void nprocinvalid() {
  using namespace nproc_mod;

  std::cout << "chooser: Unimplemented case" << std::endl;
  std::cout << "nproc=" << nproc << std::endl;
  std::exit(1);
}

static void checkminzmass(int i) {
  using namespace constants_mod;
  // Checks that the minimum invariant mass specified in the options
  // file is not zero for boson 34 (i=1) or boson 56 (i=2)
  using namespace limits_mod;
  using namespace zerowidth_mod;

  // if generating exactly on-shell, there's nothing to worry about
  if (zerowidth) return;

  if ((i == 1) && (wsqmin == zip)) {
    std::cout << std::endl;
    std::cout << "Please set m34min not equal to zero to" << std::endl;
    std::cout << "prevent the virtual photon from becoming real." << std::endl;
    std::exit(1);
  }

  if ((i == 2) && (bbsqmin == zip)) {
    std::cout << std::endl;
    std::cout << "Please set m56min not equal to zero to" << std::endl;
    std::cout << "prevent the virtual photon from becoming real." << std::endl;
    std::exit(1);
  }

  return;
}

extern "C" {
  void chooser_wrapper() {
    chooser();
  }
}

